// ─── File: src/main/java/com/bank/activity/demo/FullKafkaDemo.java ───
// Runnable demo tying together: keyed JSON producer, manual-ack consumer with
// bounded retries + DLT, batch listener, and pause/resume on DB health.
package com.bank.activity.demo;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FullKafkaDemo {

    private static final Logger log = Logger.getLogger("UserActivity");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        int partitions = 4;
        UserEventPublisher publisher = new UserEventPublisher(partitions);

        // Produce JSON events keyed by userId → ordering per user.
        publisher.publish(new UserEvent("E1", "SAV2001", "LOGIN", "ok"));
        publisher.publish(new UserEvent("E2", "SAV2001", "TRANSFER", "Rs.50000"));
        publisher.publish(new UserEvent("E3", "CUR3001", "LOGIN", "ok"));

        DatabaseHealth db = new DatabaseHealth();
        EventStore store = new EventStore();
        DeadLetter dlt = new DeadLetter();

        log.info("=== manual-ack consumer: bounded retries + DLT ===");
        UserEventConsumer consumer = new UserEventConsumer(store, dlt, db, 3);
        consumer.onEvent(new UserEvent("E2", "SAV2001", "TRANSFER", "Rs.50000")); // transient→ok
        consumer.onEvent(new UserEvent("E9", "BAD", "CORRUPT", null));            // poison→DLT

        log.info("=== batch listener: bulk process a poll batch ===");
        BatchUserEventConsumer batch = new BatchUserEventConsumer(store);
        batch.onBatch(List.of(
            new UserEvent("E4", "CUR3001", "TRANSFER", "Rs.20000"),
            new UserEvent("E5", "SAV2001", "BILLPAY", "Rs.3000")));

        log.info("=== pause when DB down, resume on recovery ===");
        ListenerControl control = new ListenerControl(consumer);
        db.setUp(false); control.onHealth(db);
        control.deliver(new UserEvent("E6", "SAV2001", "LOGOUT", "ok")); // held
        db.setUp(true); control.onHealth(db);                            // resume + drain

        log.info(() -> "stored=" + store.size() + " dlt=" + dlt.count());
    }
}

// ─── Would be in UserEvent.java ───
class UserEvent {
    final String eventId; final String userId; final String type; final String detail;
    UserEvent(String eventId, String userId, String type, String detail) {
        this.eventId = eventId; this.userId = userId; this.type = type; this.detail = detail;
    }
}

// ─── Would be in UserEventPublisher.java (keyed JSON producer) ───
class UserEventPublisher {
    private static final Logger log = Logger.getLogger("UserActivity");
    private final int partitions;
    UserEventPublisher(int partitions) { this.partitions = partitions; }
    void publish(UserEvent e) {
        int partition = Math.floorMod(e.userId.hashCode(), partitions); // key = userId
        log.info(() -> "produced JSON event " + e.eventId + " key=" + e.userId
                + " type=" + e.type + " -> partition=" + partition);
    }
}

class DatabaseHealth {
    private volatile boolean up = true;
    boolean isUp() { return up; }
    void setUp(boolean up) { this.up = up; }
}

class EventStore {
    private static final Logger log = Logger.getLogger("UserActivity");
    private final Set<String> ids = new HashSet<>();
    void save(UserEvent e) { if (ids.add(e.eventId)) log.info(() -> "stored " + e.eventId); }
    void saveAll(List<UserEvent> es) {
        for (UserEvent e : es) ids.add(e.eventId);
        log.info(() -> "bulk stored " + es.size() + " events in one DB write");
    }
    int size() { return ids.size(); }
}

class DeadLetter {
    private static final Logger log = Logger.getLogger("UserActivity");
    private int count = 0;
    void send(UserEvent e, String reason) {
        count++; log.severe(() -> "DLT event=" + e.eventId + " reason=" + reason);
    }
    int count() { return count; }
}

class TransientException extends RuntimeException { TransientException(String m){super(m);} }

// ─── Would be in UserEventConsumer.java (manual ack + bounded retries + DLT) ───
class UserEventConsumer {
    private static final Logger log = Logger.getLogger("UserActivity");
    private final EventStore store; private final DeadLetter dlt;
    private final DatabaseHealth db; private final int maxAttempts;
    private int e2Attempts = 0;
    UserEventConsumer(EventStore store, DeadLetter dlt, DatabaseHealth db, int maxAttempts) {
        this.store = store; this.dlt = dlt; this.db = db; this.maxAttempts = maxAttempts;
    }

    // In Spring: @KafkaListener(id="user", topics="user.events"); Acknowledgment injected.
    void onEvent(UserEvent e) {
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            final int a = attempt;
            try {
                process(e);
                // MANUAL_IMMEDIATE: acknowledge ONLY after success.
                log.fine(() -> "ack " + e.eventId);
                return;
            } catch (TransientException ex) {
                log.warning(() -> "transient fail " + e.eventId + " attempt " + a
                        + "/" + maxAttempts + " (backoff 500ms)");
            } catch (RuntimeException permanent) {
                dlt.send(e, permanent.getMessage());   // poison → DLT, then ack to unblock
                return;
            }
        }
        dlt.send(e, "retries exhausted");
    }

    void process(UserEvent e) {
        if (!db.isUp()) throw new TransientException("DB down");
        if ("CORRUPT".equals(e.type)) throw new IllegalArgumentException("unprocessable payload");
        if ("E2".equals(e.eventId) && e2Attempts++ == 0) throw new TransientException("blip");
        store.save(e);
    }
}

// ─── Would be in BatchUserEventConsumer.java (batch-mode listener) ───
class BatchUserEventConsumer {
    private static final Logger log = Logger.getLogger("UserActivity");
    private final EventStore store;
    BatchUserEventConsumer(EventStore store) { this.store = store; }
    // In Spring: factory.setBatchListener(true); method takes List<UserEvent> + Acknowledgment.
    void onBatch(List<UserEvent> events) {
        log.info(() -> "received batch of " + events.size());
        store.saveAll(events);     // one bulk DB write
        log.fine("ack whole batch");
    }
}

// ─── Would be in ListenerControl.java (pause/resume via endpoint registry) ───
class ListenerControl {
    private static final Logger log = Logger.getLogger("UserActivity");
    private final UserEventConsumer consumer;
    private boolean paused = false;
    private final Deque<UserEvent> held = new ArrayDeque<>();
    ListenerControl(UserEventConsumer consumer) { this.consumer = consumer; }
    void deliver(UserEvent e) {
        if (paused) { held.addLast(e); log.warning(() -> "paused; holding " + e.eventId); return; }
        consumer.onEvent(e);
    }
    void onHealth(DatabaseHealth db) {
        if (!db.isUp() && !paused) {
            paused = true; log.severe("DB down -> container.pause() (no rebalance)");
        } else if (db.isUp() && paused) {
            paused = false; log.info("DB up -> container.resume(); draining held");
            List<UserEvent> drain = new ArrayList<>(held); held.clear();
            for (UserEvent e : drain) consumer.onEvent(e);
        }
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
